 public PremiumPicker(ProfileStore value,bool previewMode) {
  store=value;preview=previewMode;Title="OpenAI Profiles - Independent launcher";Width=1080;Height=756;MinWidth=800;MinHeight=650;WindowStartupLocation=WindowStartupLocation.CenterScreen;
  WindowStyle=WindowStyle.None;AllowsTransparency=true;Background=Brushes.Transparent;ResizeMode=ResizeMode.CanResize;FontFamily=new FontFamily("Segoe UI");UseLayoutRounding=true;SnapsToDevicePixels=true;
  TextOptions.SetTextFormattingMode(this,TextFormattingMode.Display);TextOptions.SetTextRenderingMode(this,TextRenderingMode.ClearType);
  Resources.MergedDictionaries.Add((ResourceDictionary)XamlReader.Parse(Styles));surface=(Grid)XamlReader.Parse(Layout);Content=surface;
  search=Find<TextBox>("SearchField");cards=Find<WrapPanel>("CardsHost");scroller=Find<ScrollViewer>("ProfilesScroll");profileCount=Find<TextBlock>("ProfileCount");statusTitle=Find<TextBlock>("StatusTitle");statusDetail=Find<TextBlock>("StatusDetail");addButton=Find<Button>("AddTopButton");cancelButton=Find<Button>("CancelSwitch");restoreButton=Find<Button>("RestoreProfiles");closeSwitchButton=Find<Button>("CloseAndSwitch");
  closeSwitchButton.Click+=(s,e)=>{closeRequested=true;NativeApp.RequestDesktopExit();Status("Waiting for the current app to quit","If closing its window keeps it in the tray, choose Quit there. Switching continues after all sessions exit.");};
  using(var stream=typeof(PremiumPicker).Assembly.GetManifestResourceStream("OpenAI.premium.png")){if(stream!=null){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();Find<Image>("BrandLogo").Source=image;Icon=image;}}
  Find<Grid>("DragHeader").MouseLeftButtonDown+=(s,e)=>{if(e.ClickCount==2)ToggleMaximize();else if(e.LeftButton==MouseButtonState.Pressed)DragMove();};
  Find<Button>("MinimizeButton").Click+=(s,e)=>WindowState=WindowState.Minimized;Find<Button>("MaximizeButton").Click+=(s,e)=>ToggleMaximize();Find<Button>("CloseButton").Click+=(s,e)=>Close();
  addButton.Click+=(s,e)=>AddProfile();search.TextChanged+=(s,e)=>{Find<TextBlock>("SearchHint").Visibility=search.Text.Length==0?Visibility.Visible:Visibility.Collapsed;Rebuild();};
  cancelButton.Click+=(s,e)=>{pendingId=null;closeRequested=false;cancelButton.Visibility=Visibility.Collapsed;closeSwitchButton.Visibility=Visibility.Collapsed;Status("Switch canceled","Choose a profile when you're ready.");};restoreButton.Click+=(s,e)=>RestoreMenu();
  scroller.SizeChanged+=(s,e)=>SizeCards();scroller.ScrollChanged+=(s,e)=>SizeCards();timer.Interval=TimeSpan.FromSeconds(2);timer.Tick+=async(s,e)=>await RefreshProcesses();
  Loaded+=async(s,e)=>{Rebuild();InitializeFeatures();if(!preview){await RefreshProcesses();timer.Start();}};Closed+=(s,e)=>{timer.Stop();DisposeFeatures();};
  PreviewKeyDown+=(s,e)=>{if(e.Key==Key.F&&(Keyboard.Modifiers&ModifierKeys.Control)!=0){search.Focus();search.SelectAll();e.Handled=true;}};
