 T Find<T>(string name)where T:class{return surface.FindName(name)as T;}
 void ToggleMaximize(){WindowState=WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;}
 TextBlock Txt(string value,double size,string color,FontWeight weight){return new TextBlock{Text=value,FontSize=size,Foreground=B(color),FontWeight=weight};}
 Button Btn(string text,string style){return new Button{Content=text,Style=(Style)FindResource(style)};}
 string Initials(string name){var parts=name.Trim().Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries);if(parts.Length>1)return System.Globalization.StringInfo.GetNextTextElement(parts[0]).ToUpperInvariant()+System.Globalization.StringInfo.GetNextTextElement(parts[parts.Length-1]).ToUpperInvariant();return System.Globalization.StringInfo.GetNextTextElement(name).ToUpperInvariant();}
 Button MakeCard(Profile p){bool active=running.Any(x=>x.ProfileId==p.Id);var button=new Button{Height=192,Margin=new Thickness(7,3,7,13),Style=(Style)FindResource("Card"),Tag=p.Id};if(active)button.BorderBrush=B("#648472");AutomationProperties.SetName(button,"Open "+p.Name);button.ToolTip=ProfileSummary(p);
  var layout=new Grid();layout.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});layout.RowDefinitions.Add(new RowDefinition{Height=new GridLength(41)});var body=new Grid{Margin=new Thickness(18,17,13,12)};
  var avatar=new Border{Width=43,Height=43,CornerRadius=new CornerRadius(13),Background=B(ProfileColor(p,active)),HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top};var initial=Txt(Initials(p.Name),16,active?"#D7E9DE":"#E0E0E0",FontWeights.SemiBold);initial.HorizontalAlignment=HorizontalAlignment.Center;initial.VerticalAlignment=VerticalAlignment.Center;avatar.Child=initial;ApplyLogo(avatar,p);body.Children.Add(avatar);
  var dots=Btn("\u22ef","Quiet");dots.FontSize=20;dots.Width=29;dots.Height=29;dots.Padding=new Thickness(0);dots.HorizontalAlignment=HorizontalAlignment.Right;dots.VerticalAlignment=VerticalAlignment.Top;AutomationProperties.SetName(dots,"Options for "+p.Name);dots.Click+=(s,e)=>{e.Handled=true;ShowMenu(dots,p.Id);};body.Children.Add(dots);
  var name=Txt((p.Favorite?"★ ":"")+p.Name,14,"#F0F0F0",FontWeights.SemiBold);name.Margin=new Thickness(0,62,3,0);name.TextTrimming=TextTrimming.CharacterEllipsis;body.Children.Add(name);var caption=Txt(ProfileCaption(p),10.5,"#909090",FontWeights.Normal);caption.Margin=new Thickness(0,89,0,0);caption.TextTrimming=TextTrimming.CharacterEllipsis;body.Children.Add(caption);layout.Children.Add(body);
  var bottom=new Border{BorderThickness=new Thickness(0,1,0,0),BorderBrush=B("#333333"),Padding=new Thickness(18,0,17,0)};Grid.SetRow(bottom,1);var bottomGrid=new Grid();var state=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};state.Children.Add(new System.Windows.Shapes.Ellipse{Width=5,Height=5,Fill=B(active?"#A5CFB7":"#737373"),VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,7,0)});state.Children.Add(Txt(active?"Active now":"Open profile",10,active?"#C1DECC":"#AAAAAA",FontWeights.Normal));bottomGrid.Children.Add(state);var arrow=Txt("\u2197",16,"#BBBBBB",FontWeights.Normal);arrow.HorizontalAlignment=HorizontalAlignment.Right;arrow.VerticalAlignment=VerticalAlignment.Center;bottomGrid.Children.Add(arrow);bottom.Child=bottomGrid;layout.Children.Add(bottom);button.Content=layout;
  button.Click+=async(s,e)=>await RequestOpen(p.Id);button.ContextMenu=Menu(p.Id);EnableReorder(button,p.Id);button.GotKeyboardFocus+=(s,e)=>button.BringIntoView();return button;
 }
 Button MakeAddCard(){var b=new Button{Height=192,Margin=new Thickness(7,3,7,13),Style=(Style)FindResource("Card"),Background=B("#1B1B1B"),BorderBrush=B("#383838")};AutomationProperties.SetName(b,"Add profile");var stack=new StackPanel{HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};var circle=new Border{Width=37,Height=37,CornerRadius=new CornerRadius(19),BorderBrush=B("#656565"),BorderThickness=new Thickness(1),Margin=new Thickness(0,0,0,13),HorizontalAlignment=HorizontalAlignment.Center};var plus=Txt("+",25,"#CDCDCD",FontWeights.Light);plus.HorizontalAlignment=HorizontalAlignment.Center;plus.VerticalAlignment=VerticalAlignment.Center;plus.Margin=new Thickness(0,-3,0,0);circle.Child=plus;stack.Children.Add(circle);var label=Txt("Add profile",12,"#D9D9D9",FontWeights.SemiBold);label.HorizontalAlignment=HorizontalAlignment.Center;stack.Children.Add(label);var detail=Txt("Bring another account",10,"#777777",FontWeights.Normal);detail.HorizontalAlignment=HorizontalAlignment.Center;detail.Margin=new Thickness(0,7,0,0);stack.Children.Add(detail);b.Content=stack;b.Click+=(s,e)=>AddProfile();return b;}
 void SizeCards(){if(sizing||scroller==null||cards==null)return;sizing=true;try{double available=scroller.ViewportWidth;if(available<100)available=scroller.ActualWidth;if(available<100)return;available=Math.Max(190,available+14);int columns=Math.Max(1,Math.Min(4,(int)((available+4)/218)));double slot=Math.Floor(available/columns);cards.Width=available;cards.ItemWidth=slot;foreach(FrameworkElement child in cards.Children)child.Width=slot-14;}finally{sizing=false;}}
 void Rebuild(){if(cards==null)return;double offset=scroller.VerticalOffset;cards.Children.Clear();string term=search.Text.Trim();foreach(var p in store.Ordered().Where(x=>term.Length==0||x.Name.IndexOf(term,StringComparison.CurrentCultureIgnoreCase)>=0))cards.Children.Add(MakeCard(p));cards.Children.Add(MakeAddCard());profileCount.Text=store.State.Profiles.Count(x=>!x.Removed).ToString();restoreButton.Visibility=store.State.Profiles.Any(x=>x.Removed)?Visibility.Visible:Visibility.Collapsed;SizeCards();scroller.ScrollToVerticalOffset(offset);RefreshTray();}
 ContextMenu Menu(string id){var menu=new ContextMenu();menu.Resources.MergedDictionaries.Add((ResourceDictionary)XamlReader.Parse(Styles));var rename=new MenuItem{Header="Rename profile"};rename.Click+=(s,e)=>RenameProfile(id);menu.Items.Add(rename);ExtendProfileMenu(menu,id);var remove=new MenuItem{Header="Remove profile",Foreground=B("#E5A8A0")};remove.Click+=async(s,e)=>await RemoveProfile(id);menu.Items.Add(remove);return menu;}
 void ShowMenu(Button target,string id){var menu=Menu(id);menu.PlacementTarget=target;menu.Placement=System.Windows.Controls.Primitives.PlacementMode.Bottom;menu.IsOpen=true;}
 Window Dialog(string heading,string description,int height){var d=new Window{Owner=this,Title=heading,Width=452,Height=height,ResizeMode=ResizeMode.NoResize,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,WindowStartupLocation=WindowStartupLocation.CenterOwner,ShowInTaskbar=false,FontFamily=FontFamily,UseLayoutRounding=true,SizeToContent=SizeToContent.Height,MinHeight=height,MaxHeight=SystemParameters.WorkArea.Height-40};d.Resources.MergedDictionaries.Add((ResourceDictionary)XamlReader.Parse(Styles));var border=new Border{Background=B("#242424"),BorderBrush=B("#484848"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(15),Padding=new Thickness(27),Margin=new Thickness(10)};border.Effect=new System.Windows.Media.Effects.DropShadowEffect{BlurRadius=20,ShadowDepth=4,Opacity=.4};var panel=new StackPanel();var title=Txt(heading,20,"#F0F0F0",FontWeights.SemiBold);title.Margin=new Thickness(0,0,0,9);title.TextWrapping=TextWrapping.Wrap;panel.Children.Add(title);var detail=Txt(description,12,"#A0A0A0",FontWeights.Normal);detail.TextWrapping=TextWrapping.Wrap;detail.LineHeight=19;panel.Children.Add(detail);border.Child=panel;d.Content=border;return d;}
 StackPanel DialogPanel(Window d){return(StackPanel)((Border)d.Content).Child;}
 string AskName(string heading,string value){var d=Dialog(heading,"Give this account a name that's easy to recognize.",280);var panel=DialogPanel(d);var input=new TextBox{Text=value,MaxLength=60,Style=(Style)d.FindResource("Field"),Margin=new Thickness(0,21,0,22)};panel.Children.Add(input);var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};var cancel=new Button{Content="Cancel",Style=(Style)d.FindResource("Quiet"),Margin=new Thickness(0,0,8,0),IsCancel=true};cancel.Click+=(s,e)=>d.DialogResult=false;var save=new Button{Content=heading.StartsWith("Add")?"Add profile":"Save changes",Style=(Style)d.FindResource("Primary"),IsDefault=true};save.Click+=(s,e)=>d.DialogResult=true;row.Children.Add(cancel);row.Children.Add(save);panel.Children.Add(row);d.Loaded+=(s,e)=>{input.Focus();input.SelectAll();if(DialogPreviewPath!=null)d.Dispatcher.BeginInvoke(DispatcherPriority.Render,new Action(()=>{SaveWindow(d,DialogPreviewPath);d.DialogResult=false;}));};return d.ShowDialog()==true?input.Text:null;}
 void Error(Exception ex){NativeApp.Log("Error: "+ex.ToString());var d=Dialog("Couldn't complete that",ex.Message,320);var ok=new Button{Content="Got it",Style=(Style)d.FindResource("Primary"),HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,24,0,0),IsDefault=true,IsCancel=true};ok.Click+=(s,e)=>d.Close();DialogPanel(d).Children.Add(ok);d.ShowDialog();}
 bool ConfirmRemoval(string name){var d=Dialog("Remove "+name+"?","This hides the profile from the picker. Its saved login stays on this PC, and shared chats and projects are kept. You can restore it later.",290);var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,24,0,0)};var cancel=new Button{Content="Keep profile",Style=(Style)d.FindResource("Quiet"),Margin=new Thickness(0,0,8,0),IsCancel=true};cancel.Click+=(s,e)=>d.DialogResult=false;var remove=new Button{Content="Remove profile",Style=(Style)d.FindResource("Primary")};remove.Click+=(s,e)=>d.DialogResult=true;row.Children.Add(cancel);row.Children.Add(remove);DialogPanel(d).Children.Add(row);return d.ShowDialog()==true;}
 void AddProfile(){if(busy)return;string name=AskName("Add profile","");if(name==null)return;try{var p=store.Add(name);search.Clear();Rebuild();Status("Profile added",p.Name+" is ready. Open it to sign in.");}catch(Exception e){Error(e);}}
 void RenameProfile(string id){if(busy)return;var p=store.State.Profiles.Single(x=>x.Id==id);string name=AskName("Rename profile",p.Name);if(name==null)return;try{store.Rename(id,name);Rebuild();}catch(Exception e){Error(e);}}
 async Task RemoveProfile(string id){if(busy)return;try{var active=await Task.Run(()=>NativeApp.Running(store));if(active.Any(x=>x.ProfileId==id))throw new Exception("Fully quit this profile before removing it.");var p=store.State.Profiles.Single(x=>x.Id==id);if(!ConfirmRemoval(p.Name))return;store.Remove(id);if(pendingId==id){pendingId=null;closeRequested=false;cancelButton.Visibility=Visibility.Collapsed;closeSwitchButton.Visibility=Visibility.Collapsed;}Rebuild();Status("Profile removed","Its login is retained. Your shared workspace is unchanged.");}catch(Exception e){Error(e);}}
 void RestoreMenu(){var menu=new ContextMenu();menu.Resources.MergedDictionaries.Add((ResourceDictionary)XamlReader.Parse(Styles));foreach(var p in store.State.Profiles.Where(x=>x.Removed)){string id=p.Id;var item=new MenuItem{Header=p.Name};item.Click+=(s,e)=>{try{store.Restore(id);Rebuild();Status("Profile restored","Choose it whenever you're ready.");}catch(Exception ex){Error(ex);}};menu.Items.Add(item);}menu.PlacementTarget=restoreButton;menu.Placement=System.Windows.Controls.Primitives.PlacementMode.Top;menu.IsOpen=true;}
 void Status(string heading,string description){statusTitle.Text=heading;statusDetail.Text=description;}
 void SetPending(string id){pendingId=id;cancelButton.Visibility=Visibility.Visible;closeSwitchButton.Visibility=Visibility.Visible;var p=store.State.Profiles.Single(x=>x.Id==id);Status("Switch to "+p.Name+" queued",closeRequested?"If the app stays in its tray, choose Quit there. Codex sessions must also finish before switching.":NativeApp.BlockerDescription(running));}
 async Task RefreshProcesses(){if(preview||polling||busy||featureClosed)return;polling=true;try{running=await Task.Run(()=>NativeApp.Running(store));if(featureClosed)return;string signature=String.Join("|",running.Select(x=>x.ProfileId??"external").OrderBy(x=>x))+";"+String.Join("|",store.Ordered().Select(x=>x.Id+":"+AccountService.Stamp(store,x)));if(signature!=activeSignature){activeSignature=signature;Rebuild();}if(pendingId!=null&&NativeApp.CanLaunch(running)){string id=pendingId;pendingId=null;closeRequested=false;cancelButton.Visibility=Visibility.Collapsed;closeSwitchButton.Visibility=Visibility.Collapsed;await OpenNow(id);}else if(pendingId!=null)SetPending(pendingId);else if(running.Count>0){var p=store.State.Profiles.FirstOrDefault(x=>running.Any(r=>r.ProfileId==x.Id));Status(p==null?"A ChatGPT or Codex session is open":p.Name+" is open",NativeApp.BlockerDescription(running));}}catch(Exception ex){NativeApp.Log("Session check error: "+ex.GetType().Name+": "+ex.Message);Status("Unable to check open sessions","Opening is paused until the session check succeeds.");}finally{polling=false;}}
 async Task RequestOpen(string id){if(preview||busy||featureClosed||DateTime.UtcNow<suppressClickUntil)return;try{running=await Task.Run(()=>NativeApp.Running(store));if(running.Any(x=>x.ProfileId==id)){Status("This profile is already open","Continue in its native ChatGPT window.");return;}if(!NativeApp.CanLaunch(running)){NativeApp.Log("Launch queued; profile="+id+"; blockers="+running.Count);SetPending(id);return;}await OpenNow(id);}catch(Exception e){Error(e);}}
 async Task OpenNow(string id){if(busy)return;busy=true;cards.IsEnabled=false;addButton.IsEnabled=false;try{
 var p=store.State.Profiles.Single(x=>x.Id==id&&!x.Removed);
 var identity=AccountService.Cached(store,p);AccountService.ApplyExpected(identity,p);if(identity.Mismatch)throw new Exception("This saved login does not match the expected account. Check Identity & workspace in the profile menu before opening.");
 Status("1 / 4 · Checking app compatibility","Checking installed native app and the single-account guard.");
 var compatibility=await Task.Run(()=>CompatibilityService.Check());if(!compatibility.Passed)throw new Exception(compatibility.Message);
 if(store.State.TestedNativeVersion!=compatibility.Version){if(!ConfirmAction("Native app version changed",compatibility.Version+"\n\n"+compatibility.Message+"\n\nContinue with this version?","Continue"))return;store.Settings(x=>x.TestedNativeVersion=compatibility.Version);}
 Status("2 / 4 · Preparing shared history","Checking the history location and preparing a first-use backup.");
 await Task.Run(()=>NativeApp.Launch(store,p));
 Status("3 / 4 · Waiting for native window","Checking that "+p.Name+" actually opens. This can take up to 30 seconds.");
 bool opened=false;for(int i=0;i<30;i++){await Task.Delay(1000);if(await Task.Run(()=>HealthService.WindowOpened(store,p))){opened=true;break;}if(i>=3&&!((await Task.Run(()=>NativeApp.Running(store))).Any(x=>x.ProfileId==p.Id)))break;}
 if(!opened){lastFailedProfile=id;Status("Native window not confirmed","Use Tools → Retry last launch or Export diagnostics. No second instance will be forced.");Report("Launch needs attention","A visible native ChatGPT window was not detected within 30 seconds. A sign-in screen, background task or slow startup may be responsible. Retry remains protected by the one-account guard.");return;}
 lastFailedProfile=null;running=await Task.Run(()=>NativeApp.Running(store));Rebuild();
 Status("4 / 4 · Native window opened",p.Name+" is open. Confirm its account in ChatGPT; window detection does not verify login.");
 }catch(Exception e){lastFailedProfile=id;Status("The profile couldn't open","Use Retry last launch or Tools → Export diagnostics.");Error(e);}finally{busy=false;cards.IsEnabled=true;addButton.IsEnabled=true;}}

 public string DialogPreviewPath;
 public void PreviewAddDialog(string path){DialogPreviewPath=path;AskName("Add profile","");DialogPreviewPath=null;}
 static void SaveWindow(Window window,string path){window.UpdateLayout();window.Dispatcher.Invoke(DispatcherPriority.Render,new Action(()=>{}));var bitmap=new RenderTargetBitmap((int)Math.Ceiling(window.ActualWidth),(int)Math.Ceiling(window.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(path))encoder.Save(stream);}
 public void SavePreview(string path){SaveWindow(this,path);}
}
